// Original teammate textures adapted from Phaser's canvas factory to Canvas 2D.
const COZY={textures:{}};
const pixelInit=PIX.init;
PIX.init=function(){pixelInit();const textures=COZY.textures;CozyTextures.generateAllPixelTextures({textures:{exists:k=>!!textures[k],createCanvas(k,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;textures[k]=c;return {getSourceImage:()=>c,refresh(){}}},addSpriteSheet(k,c){textures[k]=c}}});
 Object.assign(PIX.tiles,{floor:textures.floor_deck,wall:textures.wall_hull,metal:textures.floor_hangar,moon:textures.lunar_ground,moon2:textures.lunar_ground,crater:textures.lunar_crater_floor});
 const aliases={bed:'prop_bed',cryo:'prop_cryo_pod',command_console:'prop_command_console',console:'prop_command_console',lab_bench:'prop_lab_bench',planter0:'prop_planter_seedling',planter1:'prop_planter',planter2:'prop_planter_ripe',water:'prop_water_dispenser',workbench:'prop_workbench',locker:'prop_locker',airlock:'lunar_airlock_ext',rock1:'lunar_rock_sm',rock2:'lunar_rock_sm',rock3:'lunar_rock_lg',ore:'lunar_ore_node',ice:'lunar_rock_sm',deposit:'lunar_rock_lg',beacon:'lunar_beacon',roverIn:'prop_rover',plant:'prop_plant_pot',desk:'prop_desk',robot:'npc_bot'};
 for(const [key,source]of Object.entries(aliases))PIX.props[key]=textures[source];
 const palette={suitMain:'#ffffff',suitShade:'#e2e8f0',trim:'#f97316',visorGlow:'#38bdf8',pack:'#64748b',hair:'#1e293b'};
 for(const color of Object.keys(PIX.sheets.astro)){const [c,g]=pcv(128,128);for(let d=0;d<4;d++)for(let f=0;f<4;f++)CozyCharacters.renderAstronautMatrixFrame(g,f*32,d*32,['down','up','left','right'][d],f?f+3:0,{...palette,trim:color==='#efbd69'?'#f97316':color});PIX.sheets.astro[color]=c;}
 for(const id of ['robot','sprout']){const [c,g]=pcv(32,32);CozyCharacters.renderNpcMatrixFrame(g,id,0,0,0,{shellLight:'#cbd5e1',shellDark:'#64748b',antenna:'#ffffff',eye:'#facc15',chestGlow:'#f1f5f9'});textures['npc_'+id]=c;}textures.npc_bot=textures.npc_robot;
 const [wall,wg]=pcv(32,32);wg.fillStyle='#0c1128';wg.fillRect(0,0,32,32);wg.fillStyle='#263359';wg.fillRect(2,0,28,32);wg.fillStyle='#364776';wg.fillRect(2,0,3,32);textures.wall_side=wall;

};
function cozyImage(g,key,x,y,scale=1){const img=COZY.textures[key];if(img)g.drawImage(img,x-img.width*scale/2,y-img.height*scale/2,img.width*scale,img.height*scale)}
function cozyStars(g,W,H){g.fillStyle='#070b1a';g.fillRect(0,0,W,H);for(let i=0;i<85;i++){g.globalAlpha=.4+(i%4)*.15;g.fillStyle=['#fde68a','#e0f2fe','#fbcfe8','#a7f3d0'][i%4];g.fillRect((i*137.23)%W,(i*73.71)%H,i%4?1:2,i%4?1:2)}g.globalAlpha=1}
function cozyMenu(g,W,H){g.save();const z=Math.max(W/480,H/270);g.translate((W-480*z)/2,(H-270*z)/2);g.scale(z,z);cozyStars(g,480,270);const x=48,y=58;
 for(let r=0;r<5;r++)for(let c=0;c<12;c++)cozyImage(g,r===0?'wall_hull':c<4?'floor_bedroom':c>=9?'floor_greenhouse':'floor_deck',x+c*32+16,y+r*32+16);
 g.fillStyle='#1e294b';g.fillRect(44,218,392,8);g.fillStyle='#235e7a';g.fillRect(44,54,392,4);
 cozyImage(g,'wall_window_earth',224,76);cozyImage(g,'wall_window_stars',352,76);
 for(const [key,px,py] of [['prop_bed',80,120],['prop_desk',134,106],['prop_plant_pot',74,190],['prop_command_console',254,122],['prop_planter',368,124],['prop_water_dispenser',404,178],['prop_plant_pot',338,192]])cozyImage(g,key,px,py);
 const astro=PIX.sheets.astro['#efbd69'];g.drawImage(astro,(Math.floor(time*2)%4)*32,0,32,32,180+Math.sin(time*.25)*10,156,32,32);cozyImage(g,'npc_bot',284,168+Math.sin(time*2));cozyImage(g,'npc_sprout',370,160+Math.sin(time)*.5,.85);
 g.globalCompositeOperation='lighter';cozyImage(g,'glow_amber',112,130,1.4);cozyImage(g,'glow_cyan',254,122,1.3);cozyImage(g,'glow_violet',368,124,1.2);g.globalCompositeOperation='source-over';g.restore();}
function cozyFloor(map,x,y){const room=map.rooms.find(r=>x>=r.x0&&x<=r.x1&&y>=r.y0&&y<=r.y1);return COZY.textures[({dorm:'floor_bedroom',food:'floor_greenhouse',greenhouse:'floor_greenhouse',lab:'floor_lab',command:'floor_lab',life:'floor_greenhouse',shield:'floor_bedroom',hangar:'floor_hangar'})[room?.key]||'floor_deck']}
function cozyRoomDecor(g,map){for(const r of map.rooms){const cx=(r.x0+r.x1+1)*16,top=r.y0*32;if(r.y1===9)cozyImage(g,['dorm','command','lab'].includes(r.key)?'wall_window_earth':'wall_window_stars',cx,top+17);cozyImage(g,'prop_plant_pot',(r.x0+1.6)*32,(r.y1-.8)*32);cozyImage(g,'prop_plant_pot',(r.x1-.6)*32,(r.y1-.8)*32);}
 cozyImage(g,'prop_desk',235,150);cozyImage(g,'npc_bot',218,225+Math.sin(time*2));}
function cozyLight(g,map){g.save();g.globalCompositeOperation='lighter';for(const r of map.rooms){const cx=(r.x0+r.x1+1)*16,cy=(r.y0+4)*32;cozyImage(g,r.key==='dorm'?'glow_amber':r.key==='greenhouse'||r.key==='shield'?'glow_violet':'glow_cyan',cx,cy,1.8)}g.restore()}
let fixedGround=null;
function cozyLunarGround(g,W,H){if(fixedGround?.width===W&&fixedGround?.height===H){g.drawImage(fixedGround,0,0);return}const output=g;fixedGround=document.createElement('canvas');fixedGround.width=W;fixedGround.height=H;g=fixedGround.getContext('2d');g.imageSmoothingEnabled=false;const tile=COZY.textures.lunar_ground;g.fillStyle='#77777b';g.fillRect(0,0,W,H);g.globalAlpha=.65;for(let y=0;y<H;y+=96)for(let x=0;x<W;x+=96)g.drawImage(tile,x,y,96,96);g.globalAlpha=1;g.fillStyle='#42475355';g.fillRect(0,0,W,H);output.drawImage(fixedGround,0,0)}
function cozyEntrances(g,map){for(const r of map.rooms){const text=roomLabel(r.key),x=(r.cx+.5)*32,y=(r.y1===9?r.y1*32+26:r.y0*32-9);g.font='bold 7px Silkscreen,monospace';const w=g.measureText(text).width+16;g.fillStyle='#0b152b';g.fillRect(x-w/2,y-10,w,17);g.strokeStyle='#6dddf2';g.lineWidth=1;g.strokeRect(x-w/2,y-10,w,17);g.fillStyle='#d2f9ff';g.textAlign='center';g.fillText(text,x,y+1);}
 cozyImage(g,'door_airlock',1184,550);g.fillStyle='#073c44';g.fillRect(1117,509,131,22);g.strokeStyle='#6ffff0';g.strokeRect(1117,509,131,22);g.fillStyle='#b8fff0';g.font='bold 8px Silkscreen,monospace';g.textAlign='center';g.fillText('LUNAR SURFACE EXIT',1184,518);g.fillText('E · AIRLOCK',1184,527);g.fillStyle='#e9bd52';g.fillRect(1160,577,48,3);g.font='bold 8px monospace';g.fillText('SURFACE → HANGAR',1115,380);}
const moduleArtCache={};
function moduleArt(key){if(!moduleArtCache[key]){const c=document.createElement('canvas');c.width=400;c.height=100;const g=c.getContext('2d');g.imageSmoothingEnabled=false;const cfg={power:['prop_command_console','prop_rover'],life:['prop_water_dispenser','prop_cryo_pod'],food:['prop_planter','prop_water_dispenser'],science:['prop_lab_bench','prop_cryo_pod'],shield:['prop_workbench','prop_locker'],telecom:['wall_window_earth','prop_command_console'],dorm:['prop_bed','prop_plant_pot'],command:['prop_command_console','wall_window_earth'],hangar:['prop_rover','prop_workbench']}[key]||['prop_command_console'];for(let y=0;y<100;y+=32)for(let x=0;x<400;x+=32)g.drawImage(COZY.textures[key==='dorm'?'floor_bedroom':key==='food'?'floor_greenhouse':'floor_lab'],x,y);cfg.forEach((k,i)=>cozyImage(g,k,130+i*155,55,1.4));if(key==='shield')g.drawImage(PIX.sheets.astro['#efbd69'],0,0,32,32,45,22,64,64);g.globalCompositeOperation='lighter';cozyImage(g,key==='dorm'?'glow_amber':'glow_cyan',200,50,2);moduleArtCache[key]=c.toDataURL();}return `<figure class="moduleArt"><img src="${moduleArtCache[key]}" alt="Pixel art of the module"><figcaption>AURORA BASE · CONNECTED SYSTEMS</figcaption></figure>`;}
